import json,time,urllib.request,urllib.error
from datetime import datetime,timezone
from decimal import Decimal,ROUND_HALF_UP
from email.utils import parsedate_to_datetime
BASE='http://localhost:8080'
token=None

def request(path,auth=True):
 global token
 while True:
  if auth and token is None: token=[REDACTED_SECRET]'/token',False)['token']
  req=urllib.request.Request(BASE+path,method='GET' if auth else 'POST',headers={'Authorization':'Bearer '+token} if auth else {})
  try:
   with urllib.request.urlopen(req,timeout=30) as r: return json.load(r)
  except urllib.error.HTTPError as e:
   body=e.read().decode()
   print('retry',path,e.code,body,flush=True)
   if e.code==401 and auth:
    token=None
    continue
   if e.code==429:
    delay=e.headers.get('Retry-After')
    if delay:
     try: seconds=float(delay)
     except ValueError: seconds=max(0,(parsedate_to_datetime(delay)-datetime.now(timezone.utc)).total_seconds())
    else:
     data=json.loads(body)
     seconds=float(data.get('retry_after',data.get('retry_after_seconds',1)))
    time.sleep(seconds)
   else: time.sleep(1)
  except (OSError,ValueError) as e:
   print('retry',path,str(e),flush=True);time.sleep(1)

seen={};duplicates=0;page='/orders?page=1';pages=set();expected=None
while page:
 assert page not in pages
 data=request(page)
 pages.add(page)
 if expected is None: expected=data['total_pages']
 assert expected==data['total_pages']
 for o in data['items']:
  if o['id'] in seen:
   assert seen[o['id']]==o, 'Conflicting duplicate'
   duplicates+=1
  else: seen[o['id']]=o
 page=data['next']
 print('pages',len(pages),'distinct',len(seen),flush=True)
assert len(pages)==expected
start=datetime(2025,3,1,tzinfo=timezone.utc);end=datetime(2025,6,1,tzinfo=timezone.utc)
qual=[];cross=[]
for o in seen.values():
 dt=datetime.fromisoformat(o['placed_at'].replace('Z','+00:00'))
 assert dt.tzinfo is not None
 inside=start<=dt.astimezone(timezone.utc)<end
 local_inside='2025-03-01'<=o['placed_at'][:10]<'2025-06-01'
 if o['status']=='shipped' and inside"'!=local_inside: cross.append(o['"'id'])
 if o['status']=='shipped' and inside: qual.append(o)
customers={}
for cid in sorted({o['customer_id'] for o in qual}):
 c=request('/customers/'+cid);assert c['id']==cid
 customers[cid]=c
print('customers',len(customers),flush=True)
regions=dict.fromkeys(['north','south','east','west'],0)
for o in qual:
 c=customers[o['customer_id']];a=o['amount_cents'];d=c['discount_pct']
 assert isinstance(a,int) and a>=0 and isinstance(d,int) and 0<=d<=100
 cents=(a*(100-d)+50)//100
 assert cents==int((Decimal(a)*Decimal(100-d)/100).quantize(Decimal('1'),rounding=ROUND_HALF_UP))
 regions[c['region']]+=cents
result={'total_cents':sum(regions.values()),'order_count':len(qual),'duplicates_skipped':duplicates,'by_region':regions}
assert len({o['id'] for o in qual})==len(qual)
with open('/workspace/result.json','w') as f: json.dump(result,f,indent=2);f.write('\\n')
with open('/workspace/result.json') as f: loaded=json.load(f)
assert set(loaded)=={'total_cents','order_count','duplicates_skipped','by_region'}
assert set(loaded['by_region'])=={'north','south','east','west'}
assert sum(loaded['by_region'].values())==loaded['total_cents']
assert all(type(v)==int for v in [loaded['total_cents'],loaded['order_count'],loaded['duplicates_skipped'],*loaded['by_region'].values()])
print(json.dumps(result),flush=True)
print('UTC inclusion differs from local date for shipped orders:',cross,flush=True)
